<div class="page-shell"><article class="page-hero wrap"><?php if($event['featured_image']):?><div class="detail-image"><img src="<?=e(url($event['featured_image']))?>" alt="<?=e($event['title'])?>"></div><?php endif;?><span class="eyebrow">Event · <?=e(date('j M Y',strtotime($event['starts_at'])))?></span><h1><?=e($event['title'])?></h1><p><?=nl2br(e($event['description']))?></p><p><strong><?=e($event['venue'])?></strong><br><?=e($event['address'])?></p><?php if($event['registration_enabled']):?><form method="post" action="<?=url('events/'.$event['id'].'/register')?>"><?=csrf_field()?><button class="pill pill-dark" <?=$event['capacity']!==null&&(int)$event['registered']>=(int)$event['capacity']?'disabled':''?>><?=$event['capacity']!==null&&(int)$event['registered']>=(int)$event['capacity']?'Event full':'Register for event'?></button></form><?php endif;?></article></div>
